"""Changed notices and the missing scope of excerpted media."""
def author(E,C,O,A,D,P,panel):
 E('plan-G3-media-06','S3','모이는 곳이 바뀌었다',
 '가상 생태 관찰 모임의 안내 두 장이다. 같은 모임 번호를 확인하고, 바뀐 항목과 그대로인 항목을 구별해 현재 안내를 써 보자. 운영팀은 나를 가를 수정한 공지라고 밝혔다.',
 '더 늦은 날짜만 보고 모든 행사가 바뀐 것으로 읽지 않는다. 모임 번호와 수정 범위, 날짜·시각의 보존을 함께 확인한다.',[
 A('explanation','현재 모임의 날짜·시각·장소를 한 문장으로 안내하고, 두 공지 중 무엇이 바뀌었는지 쓰세요.','11월21일 오전10시에 체육관 입구에서 모인다. 나 공지는 장소만 운동장 입구에서 체육관 입구로 바꾸었고 날짜와 시각은 그대로이다.',[P(1,'event'),P(2,'event'),P(2,'change')],[D('같은 모임 연결','번호 E17을 확인해 두 공지가 같은 모임의 안내임을 연결한다.','공지 날짜만 비교한다.','다른 모임의 새 안내라고 한다.'),D('수정 범위 보존','장소는 체육관 입구, 날짜·시각은 그대로라고 안내한다.','현재 장소만 쓰거나 그대로인 정보를 빠뜨린다.','날짜나 시각까지 임의로 바꾼다.')]),
 C('나 공지에서 바뀌었다고 밝힌 항목은 무엇인가요?','모이는 장소','수정 범위가 장소만이라고 명시되어 있다.',[('모임의 시각','오전10시는 그대로이다.'),('모임의 날짜','11월21일은 그대로이다.'),('모임의 번호','E17로 같은 모임이다.')],P(2,'change')),
 O('matching','가의 장소 / 나의 장소를 각각 쓰세요.','가:운동장 입구 / 나:체육관 입구',[P(1,'event'),P(2,'event')],'하나의 장소만 씀','두 장소를 바꿈'),
 O('explanation','나가 가를 고친 공지라는 것을 날짜 외에 무엇으로 확인할 수 있나요?','같은 모임 번호 E17과 장소만 수정한다는 안내로 확인한다.',[P(1,'id'),P(2,'id'),P(2,'change')],'날짜만 다시 씀','더 늦은 자료는 어떤 모임이든 모두 덮어쓴다고 함')],
 [panel('공지 가',('issuer','생태 관찰 모임 운영팀'),('id','모임 번호 E17','header'),('date','작성: 11월16일'),('event','11월21일 오전10시 · 운동장 입구')),panel('공지 나 · 수정 안내',('issuer','생태 관찰 모임 운영팀'),('id','모임 번호 E17','header'),('date','수정: 11월18일'),('event','11월21일 오전10시 · 체육관 입구'),('change','E17 공지의 장소만 수정합니다. 날짜와 시각은 그대로입니다.'))])
 E('plan-G3-media-06','S5','나중에 올린 옛 안내',
 '가상 연극 모임의 자료다. 게시한 날과 안내 자체를 고친 날이 다를 수 있다. 운영팀은 나가 현재 유효한 수정 공지이며 그 뒤 변경은 없다고 확인했다. 다는 친구가 가의 사진을 다시 올린 게시물이다.',
 '재게시 시각이 안내의 수정 시각과 같지 않음을 구별한다. 최신 날짜만으로 고르거나 이전 공지를 모두 거짓이라고 단정하지 않는다.',[
 A('explanation','어느 자료를 바탕으로 현재 시간을 안내해야 하나요? 다가 더 늦게 올라왔는데도 그대로 따를 수 없는 이유를 쓰세요.','운영팀의 나를 바탕으로 11월22일 오후2시라고 안내한다. 다는 11월18일에 올렸지만 11월12일의 옛 안내 사진을 다시 올린 것이므로 수정 공지의 내용을 바꾸지 않는다.',[P(2,'event'),P(2,'date'),P(3,'post'),P(3,'photo')],[D('현재 내용 선택','확인된 나의 오후2시를 날짜와 함께 선택한다.','나만 고르고 현재 시각을 밝히지 못한다.','다가 최근이므로 오후1시로 안내한다.'),D('두 시점 구별','다의 게시일과 사진 속 작성일이 다른 것을 수정 내용과 연결한다.','오래된 사진이라고만 하고 시점을 구별하지 못한다.','모든 재게시물은 언제나 틀렸다고 한다.')]),
 C('다에서 11월18일이 알려 주는 것은 무엇인가요?','친구가 사진을 다시 올린 날','게시 날짜이며 모임의 시간이 그날 다시 수정되었다는 뜻은 아니다.',[('운영팀이 시간을 다시 고친 날','운영팀 수정 공지는 11월16일이다.'),('연극 모임이 열리는 날','모임은 11월22일이다.'),('사진 속 안내를 처음 쓴 날','사진의 작성일은 11월12일이다.')],P(3,'post')),
 O('matching','현재 시각 / 옛 사진의 시각을 각각 쓰세요.','현재:오후2시 / 옛 사진:오후1시',[P(2,'event'),P(3,'photo')],'한 시각만 구별함','새 게시일에 옛 시각이 바뀌었다고 함'),
 O('explanation','가도 처음부터 거짓 공지였다고 할 수 있나요?','아니다. 처음에는 안내로 쓰였고 뒤에 시간이 수정된 것이다. 현재 유효하지 않은 것과 처음부터 거짓인 것은 다르다.',[P(1,'date'),P(2,'change')],'아니라고만 함','지금 다르면 과거 기록도 모두 거짓이라고 함'),
 O('revision','가장 늦게 올린 글이니까 다의 시간으로 가자라는 말을 고치세요.','다의 게시 날짜보다 원문의 수정 이력을 확인해야 한다. 지금은 나의 오후2시 안내가 유효하다.',[P(2,'change'),P(3,'photo')],'새 공지를 보자고만 하고 시점 차이가 없음','친구 게시물은 누구 것이든 볼 필요 없다고 함')],
 [panel('가 · 최초 안내',('issuer','연극 모임 운영팀'),('date','작성: 11월12일'),('event','모임 T08 · 11월22일 오후1시')),panel('나 · 운영팀 수정 공지',('date','수정: 11월16일'),('event','모임 T08 · 11월22일 오후2시','header'),('change','가의 시작 시각을 오후2시로 바꿉니다. 다른 내용은 그대로입니다.')),panel('다 · 친구 게시물',('post','사진을 올린 날: 11월18일','header'),('photo','사진 속 글: 작성 11월12일 · T08 · 11월22일 오후1시'),('note','가 안내 사진을 다시 올렸어요.'))])

 E('plan-G4-media-04','S3','일부를 옮긴 카드',
 '가상 씨앗 전시 소식이다. 가는 원문 한 문장의 앞부분을 생략해 옮긴 카드이고, 나는 원문 전체를 담은 안내이다. 가에 보이는 씨앗이라는 말이 어떤 범위를 가리키는지 전체와 연결하자.',
 '실제로 잘라 낸 웹 화면이라는 주장 대신 앞부분을 생략한 창작 카드임을 명시한다. 모두의 범위를 전체 원문에서 복원한다.',[
 A('explanation','가의 모두를 이번에 모은 씨앗 전체로 읽으면 왜 달라지나요? 나를 근거로 전시한 씨앗과 아직 전시하지 않은 씨앗을 설명하세요.','원문은 모은 씨앗 중 마른 씨앗을 모두 전시했고 젖은 씨앗은 따로 말리는 중이라고 구별한다. 가에서는 앞의 마른이라는 범위가 빠져 전체를 전시한 것처럼 읽힐 수 있다.',[P(1,'clip'),P(2,'dry'),P(2,'wet')],[D('부분·전체 연결','가에서 빠진 마른 씨앗의 범위를 나에서 복원한다.','마른 씨앗이라고만 하고 생략과 연결하지 못한다.','가의 모두를 전체 수거량으로 확정한다.'),D('상태 구별','마른 씨앗의 전시와 젖은 씨앗의 건조 중 상태를 구별한다.','전시한 씨앗만 설명한다.','젖은 씨앗도 이미 전시했다고 한다.')]),
 C('나에 따라 이미 모두 전시한 범위는 무엇인가요?','이번에 모은 것 중 마른 씨앗','원문이 전시 범위를 마른 씨앗으로 한정한다.',[('이번에 모은 씨앗 전체','젖은 씨앗은 말리는 중이다.'),('아직 젖어 있는 씨앗만','원문과 반대로 읽었다.'),('앞으로 모을 씨앗까지','미래에 모을 씨앗의 전시는 언급하지 않았다.')],P(2,'dry')),
 O('revision','가의 카드에 빠진 범위를 보충해 한 문장으로 고치세요.','이번 활동에서 모은 씨앗 중 마른 씨앗은 모두 전시했다.',P(2,'dry'),'마른 씨앗만 덧붙이고 전체와 관계가 흐림','젖은 씨앗을 모두 버렸다고 새로 씀'),
 O('explanation','젖은 씨앗을 끝내 전시하지 않을 것이라고도 단정할 수 있나요?','아니다. 지금 따로 말리고 있다는 상태만 알려 주며 이후 계획은 더 확인해야 한다.',P(2,'wet'),'모른다고만 함','지금 전시하지 않았으면 앞으로도 절대 전시하지 않는다고 함')],
 [panel('가 · 앞부분을 생략한 카드',('clip','[앞부분 생략] 씨앗은 모두 전시했다.','large'),('note','원문 문장 일부만 옮김','small')),panel('나 · 전시 소식 원문',('dry','이번 활동에서 모은 씨앗 중 마른 씨앗은 모두 전시했다.'),('wet','젖은 씨앗은 따로 말리고 있다.'),('scope','이 글은 현재의 전시 상태를 알리는 소식이다.'))])
 E('plan-G4-media-04','S5','응답한 사람과 반 전체',
 '가상 학급 소식지에 넣을 카드와 조사표다. 조사는 우리 반24명에게 물었지만 8명만 응답했다. 나머지 학생의 생각은 이 기록에 없다. 실제 조사 결과로 소개하지 않는 연습 자료다.',
 '응답자 전원의 선택을 반 전체의 생각으로 넓히지 않는다. 응답하지 않은 학생을 반대자로 분류하는 반대 방향의 오류도 구별한다.',[
 A('explanation','가의 제목을 나의 범위에 맞게 고치고, 반 전체에 관해서는 무엇을 아직 모르는지 설명하세요.','응답한 8명은 모두 소식지에 만화 코너를 원했다. 나머지16명은 응답하지 않아 생각을 모르므로 우리 반24명 전체가 원한다고 할 수 없다.',[P(1,'headline'),P(2,'target'),P(2,'response'),P(2,'result')],[D('범위 보존 제목','반 전체 대신 응답한8명이라고 밝혀 제목을 고친다.','8명을 쓰지만 모두의 대상이 여전히 반 전체로 읽힌다.','반 전체24명이 원한다는 제목을 유지한다.'),D('미응답과 반대 구별','나머지 학생의 생각은 모르며 반대라고 단정하지 않는다.','전체는 모른다고만 한다.','16명은 모두 만화를 싫어한다고 한다.')]),
 C('조사표로 바로 확인할 수 있는 것은 무엇인가요?','응답한 8명은 모두 만화 코너를 골랐다.','결과의 범위는 응답자8명이다.',[('24명 모두 같은 코너를 골랐다.','미응답16명의 생각은 없다.'),('응답하지 않은 16명은 모두 반대했다.','미응답은 반대 응답과 다르다.'),('응답한 학생 중 절반만 만화를 골랐다.','응답자는 모두 골랐다고 적혀 있다.')],P(2,'result')),
 O('matching','질문을 받은 인원 / 응답한 인원을 각각 쓰세요.','질문 대상24명 / 응답8명',[P(2,'target'),P(2,'response')],'한 인원만 구별함','대상과 응답 인원을 바꿈'),
 O('explanation','가에 모두라는 말이 있다는 이유만으로 곧바로 거짓이라고 할 수 있나요?','모두가 누구를 뜻하는지 보아야 한다. 응답자 모두는 맞지만 반 전체 모두로 넓힌 제목은 근거가 없다.',[P(1,'headline'),P(2,'result')],'범위가 다르다고만 함','모두라는 낱말은 조사 기사에 절대로 쓸 수 없다고 함'),
 O('question_generation','반 전체의 희망을 더 알아보려면 어떤 정보를 더 모아야 하나요?','아직 응답하지 않은 학생의 희망을 더 확인하되 답하지 않으면 미확인으로 남겨야 한다.',P(2,'missing'),'더 조사하자고만 함','8명의 대답을 세 번 복사하면24명 자료가 된다고 함')],
 [panel('가 · 소식지 제목 초안',('headline','우리 반 모두 만화 코너를 원해요!','large'),('note','표를 보고 만든 제목 초안','small')),panel('나 · 희망 코너 조사표',('target','질문 대상 | 우리 반 24명','header'),('response','응답 | 8명'),('result','응답 결과 | 8명 모두 만화 코너 선택'),('missing','미응답 | 16명 · 희망 코너 미확인'),kind='table')])
